import type { Match } from '@/types/match'; import type { PlayerStats } from '@/types/playerStats';
export const calculatePlayerStats=(matches:Match[],playerId:string):PlayerStats=>{const done=matches.filter(m=>m.status==='FINISHED');let appearances=0,starts=0,substituteAppearances=0,minutes=0;for(const m of done){const start=m.startingPlayers.some(p=>p.playerId===playerId),sub=m.substitutions.find(s=>s.playerInId===playerId),out=m.substitutions.find(s=>s.playerOutId===playerId);if(start||sub)appearances++;if(start){starts++;minutes+=out?.minute??m.matchDuration}else if(sub){substituteAppearances++;minutes+=m.matchDuration-sub.minute}}return{playerId,appearances,starts,substituteAppearances,minutes,goals:done.flatMap(m=>m.goals).filter(g=>g.team==='KASHIMA'&&g.scorerPlayerId===playerId&&g.goalType!=='OWN_GOAL').length,assists:done.flatMap(m=>m.goals).filter(g=>g.assistPlayerId===playerId).length,yellowCards:done.flatMap(m=>m.cards).filter(c=>c.playerId===playerId&&(c.type==='YELLOW'||c.type==='SECOND_YELLOW')).length,redCards:done.flatMap(m=>m.cards).filter(c=>c.playerId===playerId&&(c.type==='RED'||c.type==='SECOND_YELLOW')).length}};
